package main;

// v0.1 示例；正式源文件后缀为 .wz。
// 本文件展示词法、初始化、值构造和两种 for。

struct Point {
    x f64;
    y f64;
}

func squared_distance(a Point, b Point) f64 {
    let dx = a.x - b.x;
    let dy = a.y - b.y;
    return dx * dx + dy * dy;
}

func main() i32 {
    let decimal i64 = 1_024;
    let hexadecimal i64 = 0x2A;
    let binary i64 = 0b101010;
    let exponent f64 = 1.25e2;
    let text = "中文与 UTF-8\nquote: \"; slash: \\";
    let enabled = true;

    let origin = Point(x: 0.0, y: 0.0);
    let position = Point(x: 3.0, y: 4.0);
    let distance = squared_distance(origin, position);

    var count i32 = 0;
    for var i i32 = 0; i < 4; i += 1 {
        count += i;
    }
    for count < 10 {
        count += 1;
    }

    if decimal != 1024 || hexadecimal != 42 || binary != 42 {
        return 1;
    }
    if exponent != 125.0 || !enabled {
        return 2;
    }
    if distance != 25.0 || count != 10 {
        return 3;
    }
    return 0;
}

package main;

// Ordered 是本文件声明的 trait，不依赖未定义的标准库 prelude。
trait Ordered {
    func less_than(self Self, other Self) bool;
}

impl Ordered for i32 {
    func less_than(self i32, other i32) bool {
        return self < other;
    }
}

func less[T Ordered](a T, b T) bool {
    return a.less_than(b);
}

func main() i32 {
    // 元素类型由显式 Vec[i32] 上下文决定。
    let values Vec[i32] = [4, 9, 2];
    var best i32 = 0;

    for value in values {
        if less[i32](best, value) {
            best = value;
        }
    }

    if best != 9 {
        return 1;
    }
    return 0;
}

package main;

// 错误是显式类型；throws 函数中的调用自然传播，不加问号。
enum InputError {
    Negative(value i32);
    TooLarge(value i32);
}

// 本地定义的普通枚举。Result 不是隐式解包语法。
enum Result[T, E] {
    Ok(value T);
    Err(error E);
}

func checked_square(value i32) i32 throws InputError {
    if value < 0 {
        throw InputError.Negative(value);
    }
    if value > 1000 {
        throw InputError.TooLarge(value);
    }
    // 已限制到 0..1000，此处不会发生 i32 乘法溢出。
    return value * value;
}

func checked_square_result(value i32) Result[i32, InputError] {
    try {
        let answer = checked_square(value);
        return Result[i32, InputError].Ok(answer);
    } catch err InputError {
        return Result[i32, InputError].Err(err);
    }
}

func main() i32 {
    var caught = false;
    try {
        let answer = checked_square(12);
        if answer != 144 {
            return 1;
        }
        let rejected = checked_square(-3);
        return 2;
    } catch err InputError {
        switch err {
            case InputError.Negative(value):
                if value != -3 {
                    return 3;
                }
                caught = true;
            case InputError.TooLarge(value):
                return 4;
        }
    }
    if !caught {
        return 5;
    }

    let outcomes Vec[Result[i32, InputError]] = [
        checked_square_result(3),
        checked_square_result(-1),
    ];
    var successes i32 = 0;
    var failures i32 = 0;
    for outcome in outcomes {
        switch outcome {
            case Result.Ok(value):
                if value != 9 {
                    return 6;
                }
                successes += 1;
            case Result.Err(error):
                failures += 1;
        }
    }
    if successes != 1 || failures != 1 {
        return 7;
    }
    return 0;
}

