struct Point {
    x f64;
    y f64;
}

trait SquaredNorm {
    func squared_norm(self Self) f64;
}

impl SquaredNorm for Point {
    func squared_norm(self Point) f64 {
        return self.x * self.x + self.y * self.y;
    }
}

func main() i32 {
    let point = Point(x: 3.0, y: 4.0);
    let norm = point.squared_norm();
    if norm != 25.0 {
        return 1;
    }
    return 0;
}

package main;

// inout 是参数模式；调用处也明确标记。
func sum_until_zero(values Vec[i64], cleanup_count inout i64) i64 {
    // 清理代码不允许向外传播未处理的 throws。
    defer {
        cleanup_count += 1;
    }

    var total i64 = 0;
    for value in values {
        if value < 0 {
            continue;
        }
        if value == 0 {
            return total;
        }
        total += value;
    }
    return total;
}

func main() i32 {
    var cleanup_count i64 = 0;
    let total = sum_until_zero([2, -9, 3, 0, 100], inout cleanup_count);
    if total != 5 {
        return 1;
    }
    if cleanup_count != 1 {
        return 2;
    }
    return 0;
}

package main;

enum StepError {
    Negative;
}

func apply(callback func(i32) i32, value i32) i32 {
    return callback(value);
}

func positive_step(value i32) i32 throws StepError {
    if value < 0 {
        throw StepError.Negative;
    }
    return value + 1;
}

// make_step 本身不抛错；返回的函数可能抛出 StepError。
func make_step() (func(i32) i32 throws StepError) {
    return positive_step;
}

func main() i32 {
    let twice = func(value i32) i32 {
        return value * 2;
    };

    if apply(twice, 3) != 6 {
        return 1;
    }

    let callback = make_step();
    try {
        if callback(3) != 4 {
            return 2;
        }
        callback(-1);
        return 3;
    } catch error StepError {
        return 0;
    }
}

